<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {Maximize2} from 'lucide-vue-next'
import {useSandboxSession} from '~/composables/useSandboxSession'
import {useTheme} from '~/composables/useTheme'
import {LearningSandboxDesktop as SandboxDesktop,WorkbenchTerminalWindows as TerminalWindows} from '#components'
const props=defineProps<{mode:'cli'|'gui'}>()
const {sandbox,loading,notice,guiElsewhere,resumeGUI,currentUser}=useSandboxSession()
const root=ref<HTMLElement|null>(null),fullscreenError=ref(''),{initTheme}=useTheme()
onMounted(initTheme)
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{fullscreenError.value='浏览器未允许全屏，可使用浏览器全屏快捷键'}}
</script>
<template><main ref="root" class="environment-workbench"><header class="workbench-header"><strong>{{mode==='cli'?'终端工作台':'远程桌面'}}</strong><span class="spacer"/><LearningEnvironmentStatus/><button type="button" aria-label="浏览器全屏" title="浏览器全屏" @click="fullscreen"><Maximize2 :size="16"/></button><UserMenu/></header><p v-if="notice || fullscreenError" class="workbench-notice" role="status">{{notice||fullscreenError}}</p><div v-if="!currentUser" class="workbench-empty"><p>登录后使用练习环境</p><NuxtLink to="/auth">登录</NuxtLink></div><UiBusyIndicator v-else-if="loading" class="workbench-empty" label="环境加载"/><template v-else-if="sandbox.instance?.state==='running'"><div v-if="mode==='gui' && guiElsewhere" class="workbench-empty"><p>桌面已在其他页面操作</p><button @click="resumeGUI">在此继续操作</button></div><div v-else class="workbench-content"><ClientOnly><TerminalWindows v-if="mode==='cli'" :key="sandbox.instance.id" :sandbox-id="sandbox.instance.id"/><SandboxDesktop v-else :key="sandbox.instance.id" :sandbox-id="sandbox.instance.id" :active="true" :auto-resize="true"/></ClientOnly></div></template><div v-else class="workbench-empty"><UiBusyIndicator v-if="sandbox.instance && ['creating','stopping'].includes(sandbox.instance.state)" label="环境准备"/><h1 v-else>{{sandbox.instance?'环境需要处理':'启动后开始操作'}}</h1><p>使用右上角环境入口启动或查看状态。关闭此页面不会释放环境。</p></div></main></template>
<style scoped>.environment-workbench{height:100dvh;width:100%;display:flex;flex-direction:column;overflow:hidden;background:var(--bg);color:var(--ink)}.workbench-header{height:44px;flex-shrink:0;display:flex;align-items:center;gap:14px;padding:0 16px;background:var(--paper);border-bottom:1px solid var(--line);font-size:13px}.spacer{flex:1}.workbench-header>button,.workbench-empty button{border:0;border-radius:5px;background:var(--soft);color:var(--ink);cursor:pointer;padding:7px}.workbench-content{flex:1;min-height:0;overflow:hidden}.workbench-empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;color:var(--muted);font-size:14px}.workbench-empty h1{font-size:20px}.workbench-notice{padding:8px 16px;font-size:12px;color:var(--error-ink,#c66);margin:0}</style>
